				...(compilerOptions?.module ? { outputModule: true } : {})
			}
			// infrastructureLogging: compilerOptions?.cache && {
			//   debug: true,
			//   console: createLogger(infraStructureLog)
			// }
		} as TCompilerOptions<T>;
	}
}
